function CheckPinCode(input, changed, prevValue, context)
{
  if ( (input.par_pin_code =='0000' ) || (input.par_pin_code =='1111') || (input.par_pin_code =='2222') || (input.par_pin_code =='3333') || (input.par_pin_code =='4444') || 
  (input.par_pin_code =='5555' ) || (input.par_pin_code =='6666') || (input.par_pin_code =='7777') || (input.par_pin_code =='8888') || (input.par_pin_code =='9999') ||  
  (input.par_pin_code =='1234' ) || (input.par_pin_code.length != 4) ) return ApplicationProgram.getMessage("msg_pin_code");
  return true;
}


function count_3(input, output, context)
{
  output.result = input.wa1 + input.wa2 + input.wa3;
}

function count_3_RL(input, output, context)
{
  output.wa1 = 0;
  output.wa2 = 0;
  output.wa3 = 0;  
}


function count_5(input, output, context)
{
  output.result = input.wa1 + input.wa2 + input.wa3 + input.wa4 + input.wa5;
}

function count_5_RL(input, output, context)
{
  output.wa1 = 0;
  output.wa2 = 0;
  output.wa3 = 0;
  output.wa4 = 0;
  output.wa5 = 0;    
}


